// Production SVG generated by the integration test, loaded without network/font access.
import assert from "node:assert/strict";
import { readFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { PipelineWorker } from "../../worker/pipeline.mjs";
const scene = JSON.parse(await readFile(process.argv[3], "utf8"));
for (const font of scene.fonts) {
  const file = font.id === "lato" ? "fixtures/fonts/Lato-Regular.ttf" : "renderer/fonts/NotoSans.ttf";
  font.url = `data:font/ttf;base64,${(await readFile(file)).toString("base64")}`;
}
const worker = await PipelineWorker.start();
try {
  await worker.resources(scene.fonts, []);
  await worker.render(scene);
  const canvas = await worker.runtime.page.evaluate(() => document.getElementById("scene").toDataURL());
  const page = await worker.runtime.browser.newPage({ offline: true });
  const network = [];
  page.on("request", request => { if (/^https?:/.test(request.url())) network.push(request.url()); });
  await page.goto(pathToFileURL(process.argv[2]).href);
  await page.evaluate(async () => {
    await document.fonts.ready;
    // SVG root is the viewport, without the browser's default HTML body margin.
    document.documentElement.style.margin = "0";
  });
  const geometry = await page.evaluate(() => [...document.querySelectorAll("text")].map(text => ({ text: text.textContent, x: +text.getAttribute("x"), y: +text.getAttribute("y"), spacing: +text.getAttribute("letter-spacing") })));
  const expected = scene.nodes.flatMap(n => n.lines.map(l => ({ text: l.text, x: n.bounds.x + l.x, y: n.bounds.y + l.y, spacing: n.letterSpacing ?? 0 })));
  assert.deepEqual(geometry, expected);
  assert.deepEqual(network, []);
  const png = await page.locator("svg").screenshot();
  const difference = await worker.runtime.page.evaluate(async ({ canvas, svg }) => {
    const decode = async src => { const i = new Image(); i.src = src; await i.decode(); const c = document.createElement("canvas"); c.width = i.width; c.height = i.height; c.getContext("2d").drawImage(i, 0, 0); return c.getContext("2d").getImageData(0, 0, i.width, i.height).data; };
    const a = await decode(canvas), b = await decode(`data:image/png;base64,${svg}`);
    let pixels = 0, maxDelta = 0;
    for (let p = 0; p < a.length; p += 4) if ([0, 1, 2, 3].some(i => a[p + i] !== b[p + i])) { pixels++; maxDelta = Math.max(maxDelta, ...[0, 1, 2, 3].map(i => Math.abs(a[p + i] - b[p + i]))); }
    return { pixels, maxDelta };
  }, { canvas, svg: png.toString("base64") });
  assert.equal(difference.pixels, 0, JSON.stringify(difference));
  const artifacts = path.resolve("docs/text-properties-evidence");
  await mkdir(artifacts, { recursive: true });
  await page.locator("svg").screenshot({ path: path.join(artifacts, "production-svg.png") });
  await worker.runtime.page.locator("#scene").screenshot({ path: path.join(artifacts, "canvas.png") });
  console.log(JSON.stringify({ lines: geometry.length, network, difference, artifacts }));
} finally { await worker.close(); }
